import { SearchParamsContext } from 'next/dist/shared/lib/hooks-client-context.shared-runtime';
import { useState } from 'react';
import AgencyCalendarWorkspace from '@/components/AgencyCalendarWorkspace';
import operatingStyles from '@/components/AgencyOperatingWorkspace.module.css';
let tasks:any[]=[];
let failSave=false,failBirthdays=false,failReads=false,inactiveOwner=false;
const rpc=async<T,>(name:string,args:any={}):Promise<T>=>{
 if(typeof window!=='undefined'){const qa=window as any;qa.calendarReads??=[];qa.calendarReads.push({name,args});}
 if(typeof window!=='undefined'&&!(window as any).releaseStalls&&((new URLSearchParams(window.location.search).has('stalled')&&name==='redream_calendar_range')||(new URLSearchParams(window.location.search).has('stalledTasks')&&name==='redream_calendar_tasks_v1')))return new Promise(()=>{});
 if(name==='redream_calendar_task_assignees_v1')return {items:[{user_id:'qa-user',display_name:'Jesse'},...(!inactiveOwner?[{user_id:'colleague',display_name:'Colleague'}]:[])]}as T;
 if(name==='redream_calendar_task_create_v1'){if(failSave)throw new Error('task_owner_inactive');const input=args.p_input;const task={...input,id:input.id,tenant_id:args.p_tenant_id,creator_user_id:'qa-user',owner_user_id:input.owner_user_id||'qa-user',owner_name:input.owner_user_id==='colleague'?'Colleague':'Jesse',status:'open',revision:1,archived_at:null,can_edit:true,needs_reassignment:false,due_at:null,notes:input.notes||''};tasks.push(task);return {task}as T;}
 if(name==='redream_calendar_task_update_v1'){if(failSave)throw new Error('task_revision_conflict');const task=tasks.find(t=>t.id===args.p_task_id);if(task.revision!==args.p_expected_revision)throw new Error('task_revision_conflict');if(args.p_action==='edit'){if(inactiveOwner&&task.visibility==='company'&&(args.p_input.owner_user_id||task.owner_user_id)==='colleague')throw new Error('task_owner_inactive');Object.assign(task,args.p_input);}else if(args.p_action==='complete')task.status='done';else if(args.p_action==='reopen')task.status='open';else if(args.p_action==='archive')task.archived_at=new Date().toISOString();else if(args.p_action==='restore')task.archived_at=null;task.revision++;return {task:{...task}}as T;}
 if(name==='redream_calendar_tasks_v1'){if(failReads)throw new Error('offline');const items=tasks.filter(t=>t.tenant_id===args.p_tenant_id&&(!t.archived_at||args.p_include_archived)&&(t.status==='open'||args.p_include_done)).filter(t=>args.p_mode==='undated'?!t.due_on:args.p_mode==='overdue'?false:t.due_on>=args.p_start&&t.due_on<args.p_end);return {items:items.map(t=>({...t})),next_cursor:null,count:items.length}as T;}
 if(name==='redream_calendar_birthdays'){if(failBirthdays)throw new Error('offline');return {items:[{item_id:'birthday',date_at:args.p_start,title:"Dylan's birthday",birthday_category:'players',player_id:'player'}]}as T;}
 return {meetings:{items:[{meeting_id:'meeting',title:'Club meeting',starts_at:args.p_start+'T20:00:00',person_name:'Club contact'}]},follow_ups:{items:[]},operations:{deadlines:{items:[]}}}as T;
};
export default function Page(){const [tenant,setTenant]=useState('qa-tenant');return <SearchParamsContext.Provider value={new URLSearchParams()}><main className={operatingStyles.root} style={{maxWidth:1150,margin:'0 auto',padding:16,fontFamily:'Arial,sans-serif',background:'#f5f7f9','--agency-primary':'#12364c'}as any}><h1>Calendar</h1><div className={operatingStyles.viewStage}><AgencyCalendarWorkspace key={tenant} tenantId={tenant} userId="qa-user" preferenceKey={`${tenant}:qa-user`} data={{}} basePath="/qa-calendar" rpc={rpc} onRecordMeetingOutcome={()=>{}}/></div><nav aria-label="Fixture navigation" style={{position:"fixed",bottom:20,left:20,right:20,height:70,zIndex:1000,background:"white"}}>Home Players Calendar</nav><button aria-label="Fixture microphone" style={{position:"fixed",bottom:110,right:20,zIndex:10000}}>Mic</button><button onClick={()=>{failSave=!failSave;}}>Toggle save failure</button><button onClick={()=>{failBirthdays=!failBirthdays;window.dispatchEvent(new Event('redream:birthdays-updated'));}}>Toggle birthday failure</button><button onClick={()=>{inactiveOwner=!inactiveOwner;}}>Toggle inactive owner</button><button onClick={()=>{failReads=!failReads;}}>Toggle task read failure</button><button onClick={()=>{const task=tasks.find(t=>t.title==='Revised shortlist');task.title='Other session shortlist';task.revision++;}}>Concurrent edit</button><button onClick={()=>setTenant(tenant==='qa-tenant'?'other-tenant':'qa-tenant')}>Switch tenant</button></main></SearchParamsContext.Provider>;}
